49: static inline void emit(struct internal_state *state,
50:                         uint32_t data, int bits)
51: {
52:     /**
53:        Emit sequence of bits.
54:      */
55: 
56:     if (bits <= state->bits) {
57:         state->bits -= bits;
58:         *state->cds += (uint8_t)(data << state->bits);
59:     } else {
60:         bits -= state->bits;
61:         *state->cds++ += (uint8_t)((uint64_t)data >> bits);
62: 
63:         while (bits > 8) {
64:             bits -= 8;
65:             *state->cds++ = (uint8_t)(data >> bits);
66:         }
67: 
68:         state->bits = 8 - bits;
69:         *state->cds = (uint8_t)(data << state->bits);
70:     }
71: }
