260: 
261:     uint32_t D;
262:     struct internal_state *state = strm->state;
263:     uint32_t *x = state->data_raw;
264:     uint32_t *d = state->data_pp;
265:     uint32_t xmax = state->xmax;
266:     uint32_t xmin = state->xmin;
267:     uint32_t rsi = strm->rsi * strm->block_size - 1;
268:     uint32_t m = UINT32_C(1) << (strm->bits_per_sample - 1);
269: 
270:     state->ref = 1;
271:     state->ref_sample = x[0];
272:     d[0] = 0;
273:     /* Sign extension */
274:     x[0] = (x[0] ^ m) - m;
275: 
276:     for (size_t i = 0; i < rsi; i++) {
277:         x[i + 1] = (x[i + 1] ^ m) - m;
278:         if ((int32_t)x[i + 1] < (int32_t)x[i]) {
279:             D = x[i] - x[i + 1];
280:             if (D <= xmax - x[i])
281:                 d[i + 1] = 2 * D - 1;
282:             else
283:                 d[i + 1] = xmax - x[i + 1];
284:         } else {
285:             D = x[i + 1] - x[i];
286:             if (D <= x[i] - xmin)
287:                 d[i + 1] = 2 * D;
288:             else
289:                 d[i + 1] = x[i + 1] - xmin;
290:         }
291:     }
292:     state->uncomp_len = (strm->block_size - 1) * strm->bits_per_sample;
293: }
294: 
295: static inline uint64_t block_fs(struct aec_stream *strm, int k)
296: {
297:     /**
298:        Sum FS of all samples in block for given splitting position.
299:     */
300: 
301:     struct internal_state *state = strm->state;
302:     uint64_t fs = 0;
303: 
304:     for (size_t i = 0; i < strm->block_size; i++)
305:         fs += (uint64_t)(state->block[i] >> k);
306: 
307:     return fs;
308: }
309: 
310: static uint32_t assess_splitting_option(struct aec_stream *strm)
311: {
312:     /**
313:        Length of CDS encoded with splitting option and optimal k.
314: 
315:        In Rice coding each sample in a block of samples is split at
316:        the same position into k LSB and bits_per_sample - k MSB. The
317:        LSB part is left binary and the MSB part is coded as a
318:        fundamental sequence a.k.a. unary (see CCSDS 121.0-B-3). The
319:        function of the length of the Coded Data Set (CDS) depending on
320:        k has exactly one minimum (see A. Kiely, IPN Progress Report
321:        42-159).
322: 
323:        To find that minimum with only a few costly evaluations of the
324:        CDS length, we start with the k of the previous CDS. K is
325:        increased and the CDS length evaluated. If the CDS length gets
326:        smaller, then we are moving towards the minimum. If the length
327:        increases, then the minimum will be found with smaller k.
328: 
329:        For increasing k we know that we will gain block_size bits in
330:        length through the larger binary part. If the FS length is less
331:        than the block size then a reduced FS part can't compensate the
332:        larger binary part. So we know that the CDS for k+1 will be
333:        larger than for k without actually computing the length. An
334:        analogue check can be done for decreasing k.
335:      */
336: 
337:     struct internal_state *state = strm->state;
338: 
339:     /* Block size of current block */
340:     uint64_t this_bs = strm->block_size - state->ref;
341: 
342:     /* CDS length minimum so far */
343:     uint64_t len_min = UINT64_MAX;
344: 
345:     int k = state->k;
346:     int k_min = k;
347: 
348:     /* 1 if we shouldn't reverse */
349:     int no_turn = (k == 0);
350: 
351:     /* Direction, 1 means increasing k, 0 decreasing k */
352:     int dir = 1;
353: 
354:     for (;;) {
355:         /* Length of FS part (not including 1s) */
356:         uint64_t fs_len = block_fs(strm, k);
357: 
358:         /* CDS length for current k */
359:         uint64_t len = fs_len + this_bs * (k + 1);
360: 
361:         if (len < len_min) {
362:             if (len_min < UINT64_MAX)
363:                 no_turn = 1;
364: 
365:             len_min = len;
366:             k_min = k;
367: 
368:             if (dir) {
369:                 if (fs_len < this_bs || k >= state->kmax) {
370:                     if (no_turn)
371:                         break;
372:                     k = state->k - 1;
373:                     dir = 0;
374:                     no_turn = 1;
375:                 } else {
376:                     k++;
377:                 }
378:             } else {
379:                 if (fs_len >= this_bs || k == 0)
380:                     break;
381:                 k--;
382:             }
383:         } else {
384:             if (no_turn)
385:                 break;
386:             k = state->k - 1;
387:             dir = 0;
388:             no_turn = 1;
389:         }
390:     }
391:     state->k = k_min;
392: 
393:     return (uint32_t)len_min;
394: }
395: 
396: static uint32_t assess_se_option(struct aec_stream *strm)
397: {
398:     /**
399:        Length of CDS encoded with Second Extension option.
400: 
401:        If length is above limit just return UINT32_MAX.
402:     */
403: 
404:     struct internal_state *state = strm->state;
405:     uint32_t *block = state->block;
406:     uint64_t len = 1;
407: 
408:     for (size_t i = 0; i < strm->block_size; i += 2) {
409:         uint64_t d = (uint64_t)block[i] + (uint64_t)block[i + 1];
410:         len += d * (d + 1) / 2 + block[i + 1] + 1;
411:         if (len > state->uncomp_len)
412:             return UINT32_MAX;
413:     }
414: 
415:     return (uint32_t)len;
416: }
417: 
418: static void init_output(struct aec_stream *strm)
419: {
420:     /**
421:        Direct output to next_out if next_out can hold a Coded Data
422:        Set, use internal buffer otherwise.
423:     */
424: 
425:     struct internal_state *state = strm->state;
426: 
427:     if (strm->avail_out > state->cds_len) {
428:         if (!state->direct_out) {
429:             state->direct_out = 1;
430:             *strm->next_out = *state->cds;
431:             state->cds = strm->next_out;
432:         }
433:     } else {
434:         if (state->zero_blocks == 0 || state->direct_out) {
435:             /* copy leftover from last block */
436:             *state->cds_buf = *state->cds;
437:             state->cds = state->cds_buf;
438:         }
439:         state->direct_out = 0;
440:     }
441: }
