443: /*
444:  *
445:  * FSM functions
446:  *
447:  */
448: 
449: static int m_flush_block_resumable(struct aec_stream *strm)
450: {
451:     /**
452:        Slow and restartable flushing
453:     */
454:     struct internal_state *state = strm->state;
455: 
456:     int n = (int)MIN((size_t)(state->cds - state->cds_buf - state->i),
457:                      strm->avail_out);
458:     memcpy(strm->next_out, state->cds_buf + state->i, n);
459:     strm->next_out += n;
460:     strm->avail_out -= n;
461:     state->i += n;
462: 
463:     if (strm->avail_out == 0) {
464:         return M_EXIT;
465:     } else {
466:         state->mode = m_get_block;
467:         return M_CONTINUE;
468:     }
469: }
470: 
471: static int m_flush_block(struct aec_stream *strm)
472: {
473:     /**
474:        Flush block in direct_out mode by updating counters.
475: 
476:        Fall back to slow flushing if in buffered mode.
477:     */
478:     struct internal_state *state = strm->state;
479: 
480: #ifdef ENABLE_RSI_PADDING
481:     if (state->blocks_avail == 0 &&
482:         strm->flags & AEC_PAD_RSI &&
483:         state->block_nonzero == 0)
484:             emit(state, 0, state->bits % 8);
485: #endif
486: 
487:     if (state->direct_out) {
488:         int n = (int)(state->cds - strm->next_out);
489:         strm->next_out += n;
490:         strm->avail_out -= n;
491:         state->mode = m_get_block;
492: 
493:         if (state->ready_to_capture_rsi &&
494:             state->blocks_avail == 0 &&
495:             state->offsets != NULL) {
496:                 vector_push_back(state->offsets, (strm->total_out - strm->avail_out) * 8 + (8 - state->bits));
497:                 state->ready_to_capture_rsi = 0;
498:         }
499: 
500:         return M_CONTINUE;
501:     }
502: 
503:     state->i = 0;
504:     state->mode = m_flush_block_resumable;
505:     return M_CONTINUE;
506: }
507: 
508: static int m_encode_splitting(struct aec_stream *strm)
509: {
510:     struct internal_state *state = strm->state;
511:     int k = state->k;
512: 
513:     emit(state, k + 1, state->id_len);
514:     if (state->ref)
515:         emit(state, state->ref_sample, strm->bits_per_sample);
516: 
517:     emitblock_fs(strm, k, state->ref);
518:     if (k)
519:         emitblock(strm, k, state->ref);
520: 
521:     return m_flush_block(strm);
522: }
523: 
524: static int m_encode_uncomp(struct aec_stream *strm)
525: {
526:     struct internal_state *state = strm->state;
527: 
528:     emit(state, (1U << state->id_len) - 1, state->id_len);
529:     if (state->ref)
530:         state->block[0] = state->ref_sample;
531:     emitblock(strm, strm->bits_per_sample, 0);
532:     return m_flush_block(strm);
533: }
534: 
535: static int m_encode_se(struct aec_stream *strm)
536: {
537:     struct internal_state *state = strm->state;
538: 
539:     emit(state, 1, state->id_len + 1);
540:     if (state->ref)
541:         emit(state, state->ref_sample, strm->bits_per_sample);
542: 
543:     for (size_t i = 0; i < strm->block_size; i+= 2) {
544:         uint32_t d = state->block[i] + state->block[i + 1];
545:         emitfs(state, d * (d + 1) / 2 + state->block[i + 1]);
546:     }
547: 
548:     return m_flush_block(strm);
549: }
550: 
551: static int m_encode_zero(struct aec_stream *strm)
552: {
553:     struct internal_state *state = strm->state;
554: 
555:     emit(state, 0, state->id_len + 1);
556: 
557:     if (state->zero_ref)
558:         emit(state, state->zero_ref_sample, strm->bits_per_sample);
559: 
560:     if (state->zero_blocks == ROS)
561:         emitfs(state, 4);
562:     else if (state->zero_blocks >= 5)
563:         emitfs(state, state->zero_blocks);
564:     else
565:         emitfs(state, state->zero_blocks - 1);
566: 
567:     state->zero_blocks = 0;
568:     return m_flush_block(strm);
569: }
570: 
571: static int m_select_code_option(struct aec_stream *strm)
572: {
573:     /**
574:        Decide which code option to use.
575:     */
576: 
577:     struct internal_state *state = strm->state;
578: 
579:     uint32_t split_len;
580:     uint32_t se_len;
581:     if (state->id_len > 1)
582:         split_len = assess_splitting_option(strm);
583:     else
584:         split_len = UINT32_MAX;
585:     se_len = assess_se_option(strm);
586: 
587:     if (split_len < state->uncomp_len) {
588:         if (split_len < se_len)
589:             return m_encode_splitting(strm);
590:         else
591:             return m_encode_se(strm);
592:     } else {
593:         if (state->uncomp_len <= se_len)
594:             return m_encode_uncomp(strm);
595:         else
596:             return m_encode_se(strm);
597:     }
598: }
599: 
600: static int m_check_zero_block(struct aec_stream *strm)
601: {
602:     /**
603:        Check if input block is all zero.
604: 
605:        Aggregate consecutive zero blocks until we find !0 or reach the
606:        end of a segment or RSI.
607:     */
608: 
609:     struct internal_state *state = strm->state;
610:     uint32_t *p = state->block;
611: 
612:     size_t i;
613:     for (i = 0; i < strm->block_size; i++)
614:         if (p[i] != 0)
615:             break;
616: 
617:     if (i < strm->block_size) {
618:         if (state->zero_blocks) {
619:             /* The current block isn't zero but we have to emit a
620:              * previous zero block first. The current block will be
621:              * flagged and handled later.
622:              */
623:             state->block_nonzero = 1;
624:             state->mode = m_encode_zero;
625:             return M_CONTINUE;
626:         }
627:         state->mode = m_select_code_option;
628:         return M_CONTINUE;
629:     } else {
630:         state->zero_blocks++;
631:         if (state->zero_blocks == 1) {
632:             state->zero_ref = state->ref;
633:             state->zero_ref_sample = state->ref_sample;
634:         }
635:         if (state->blocks_avail == 0 || state->blocks_dispensed % 64 == 0) {
636:             if (state->zero_blocks > 4)
637:                 state->zero_blocks = ROS;
638: 
639:             state->mode = m_encode_zero;
640:             return M_CONTINUE;
641:         }
642:         state->mode = m_get_block;
643:         return M_CONTINUE;
644:     }
645: }
646: 
647: static int m_get_rsi_resumable(struct aec_stream *strm)
648: {
649:     /**
650:        Get RSI while input buffer is short.
651: 
652:        Let user provide more input. Once we got all input, pad buffer
653:        to full RSI.
654:     */
655: 
656:     struct internal_state *state = strm->state;
657: 
658:     do {
659:         if (strm->avail_in >= state->bytes_per_sample) {
660:             state->data_raw[state->i] = state->get_sample(strm);
661:         } else {
662:             if (state->flush == AEC_FLUSH) {
663:                 if (state->i > 0) {
664:                     state->blocks_avail = state->i / strm->block_size - 1;
665:                     if (state->i % strm->block_size)
666:                         state->blocks_avail++;
667:                     /* Pad raw buffer with last sample. Only encode
668:                      * blocks_avail will be encoded later. */
669:                     do
670:                         state->data_raw[state->i] =
671:                             state->data_raw[state->i - 1];
672:                     while(++state->i < strm->rsi * strm->block_size);
673:                 } else {
674:                     /* Finish encoding by padding the last byte with
675:                      * zero bits. */
676:                     emit(state, 0, state->bits);
677:                     if (strm->avail_out > 0) {
678:                         if (!state->direct_out)
679:                             *strm->next_out++ = *state->cds;
680:                         strm->avail_out--;
681:                         state->flushed = 1;
682:                     }
683:                     return M_EXIT;
684:                 }
685:             } else {
686:                 return M_EXIT;
687:             }
688:         }
689:     } while (++state->i < strm->rsi * strm->block_size);
690: 
691:     if (strm->flags & AEC_DATA_PREPROCESS)
692:         state->preprocess(strm);
693: 
694:     return m_check_zero_block(strm);
695: }
696: 
697: static int m_get_block(struct aec_stream *strm)
698: {
699:     /**
700:        Provide the next block of preprocessed input data.
701: 
702:        Pull in a whole Reference Sample Interval (RSI) of data if
703:        block buffer is empty.
704:     */
705: 
706:     struct internal_state *state = strm->state;
707: 
708:     init_output(strm);
709: 
710:     if (state->block_nonzero) {
711:         state->block_nonzero = 0;
712:         state->mode = m_select_code_option;
713:         return M_CONTINUE;
714:     }
715: 
716:     if (state->blocks_avail == 0) {
717:         state->blocks_avail = strm->rsi - 1;
718:         state->block = state->data_pp;
719:         state->blocks_dispensed = 1;
720:         if (strm->avail_in >= state->rsi_len) {
721:             state->ready_to_capture_rsi = 1;
722:             state->get_rsi(strm);
723:             if (strm->flags & AEC_DATA_PREPROCESS)
724:                 state->preprocess(strm);
725: 
726:             return m_check_zero_block(strm);
727:         } else {
728:             state->i = 0;
729:             state->mode = m_get_rsi_resumable;
730:         }
731:     } else {
732:         if (state->ref) {
733:             state->ref = 0;
734:             state->uncomp_len = strm->block_size * strm->bits_per_sample;
735:         }
736:         state->block += strm->block_size;
737:         state->blocks_dispensed++;
738:         state->blocks_avail--;
739:         return m_check_zero_block(strm);
740:     }
741:     return M_CONTINUE;
742: }
743: 
744: static void cleanup(struct aec_stream *strm)
745: {
746:     struct internal_state *state = strm->state;
747: 
748:     if (strm->flags & AEC_DATA_PREPROCESS && state->data_raw)
749:         free(state->data_raw);
750:     if (state->data_pp)
751:         free(state->data_pp);
752:     if (state->cds_buf)
753:         free(state->cds_buf);
754:     free(state);
755: }
