757: /*
758:  *
759:  * API functions
760:  *
761:  */
762: 
763: int aec_encode_init(struct aec_stream *strm)
764: {
765:     struct internal_state *state;
766: 
767:     if (strm->bits_per_sample > 32
768:         || strm->bits_per_sample == 0
769:         || strm->rsi > 4096
770:         || strm->rsi == 0)
771:         return AEC_CONF_ERROR;
772: 
773:     if (strm->flags & AEC_NOT_ENFORCE) {
774:         /* Allow non-standard block sizes */
775:         if (strm->block_size & 1
776:             || strm->block_size == 0
777:             || strm->block_size > 256)
778:             return AEC_CONF_ERROR;
779:     } else {
780:         /* Only allow standard conforming block sizes */
781:         if (strm->block_size != 8
782:             && strm->block_size != 16
783:             && strm->block_size != 32
784:             && strm->block_size != 64)
785:             return AEC_CONF_ERROR;
786:     }
787: 
788:     state = malloc(sizeof(struct internal_state));
789:     if (state == NULL)
790:         return AEC_MEM_ERROR;
791: 
792:     memset(state, 0, sizeof(struct internal_state));
793:     strm->state = state;
794:     state->uncomp_len = strm->block_size * strm->bits_per_sample;
795: 
796:     if (strm->bits_per_sample > 16) {
797:         /* 24/32 input bit settings */
798:         state->id_len = 5;
799: 
800:         if (strm->bits_per_sample <= 24
801:             && strm->flags & AEC_DATA_3BYTE) {
802:             state->bytes_per_sample = 3;
803:             if (strm->flags & AEC_DATA_MSB) {
804:                 state->get_sample = aec_get_msb_24;
805:                 state->get_rsi = aec_get_rsi_msb_24;
806:             } else {
807:                 state->get_sample = aec_get_lsb_24;
808:                 state->get_rsi = aec_get_rsi_lsb_24;
809:             }
810:         } else {
811:             state->bytes_per_sample = 4;
812:             if (strm->flags & AEC_DATA_MSB) {
813:                 state->get_sample = aec_get_msb_32;
814:                 state->get_rsi = aec_get_rsi_msb_32;
815:             } else {
816:                 state->get_sample = aec_get_lsb_32;
817:                 state->get_rsi = aec_get_rsi_lsb_32;
818:             }
819:         }
820:     }
821:     else if (strm->bits_per_sample > 8) {
822:         /* 16 bit settings */
823:         state->id_len = 4;
824:         state->bytes_per_sample = 2;
825: 
826:         if (strm->flags & AEC_DATA_MSB) {
827:             state->get_sample = aec_get_msb_16;
828:             state->get_rsi = aec_get_rsi_msb_16;
829:         } else {
830:             state->get_sample = aec_get_lsb_16;
831:             state->get_rsi = aec_get_rsi_lsb_16;
832:         }
833:     } else {
834:         /* 8 bit settings */
835:         if (strm->flags & AEC_RESTRICTED) {
836:             if (strm->bits_per_sample <= 4) {
837:                 if (strm->bits_per_sample <= 2)
838:                     state->id_len = 1;
839:                 else
840:                     state->id_len = 2;
841:             } else {
842:                 free(state);
843:                 return AEC_CONF_ERROR;
844:             }
845:         } else {
846:             state->id_len = 3;
847:         }
848:         state->bytes_per_sample = 1;
849: 
850:         state->get_sample = aec_get_8;
851:         state->get_rsi = aec_get_rsi_8;
852:     }
853:     state->rsi_len = strm->rsi * strm->block_size * state->bytes_per_sample;
854: 
855:     if (strm->flags & AEC_DATA_SIGNED) {
856:         state->xmax = (INT64_C(1) << (strm->bits_per_sample - 1)) - 1;
857:         state->xmin = ~state->xmax;
858:         state->preprocess = preprocess_signed;
859:     } else {
860:         state->xmax = (UINT64_C(1) << strm->bits_per_sample) - 1;
861:         state->xmin = 0;
862:         state->preprocess = preprocess_unsigned;
863:     }
864: 
865:     state->kmax = (1U << state->id_len) - 3;
866: 
867:     /* Maximum CDS length. We need extra 8 bytes for copy64() */
868:     state->cds_len = (state->id_len + strm->block_size
869:                       * strm->bits_per_sample) / 8 + 1 + 8;
870:     state->cds_buf = malloc(state->cds_len);
871:     if (state->cds_buf == NULL) {
872:         cleanup(strm);
873:         return AEC_MEM_ERROR;
874:     }
875:     state->data_pp = malloc(strm->rsi
876:                             * strm->block_size
877:                             * sizeof(uint32_t));
878:     if (state->data_pp == NULL) {
879:         cleanup(strm);
880:         return AEC_MEM_ERROR;
881:     }
882: 
883:     if (strm->flags & AEC_DATA_PREPROCESS) {
884:         state->data_raw = malloc(strm->rsi
885:                                  * strm->block_size
886:                                  * sizeof(uint32_t));
887:         if (state->data_raw == NULL) {
888:             cleanup(strm);
889:             return AEC_MEM_ERROR;
890:         }
891:     } else {
892:         state->data_raw = state->data_pp;
893:     }
894: 
895:     state->block = state->data_pp;
896: 
897:     state->ref = 0;
898:     strm->total_in = 0;
899:     strm->total_out = 0;
900:     state->flushed = 0;
901: 
902:     state->cds = state->cds_buf;
903:     *state->cds = 0;
904:     state->bits = 8;
905:     state->mode = m_get_block;
906:     state->ready_to_capture_rsi = 0;
907:     return AEC_OK;
908: }
