193: static inline uint32_t direct_get(struct aec_stream *strm, int n)
194: {
195:     /**
196:        Get n bit from input stream
197: 
198:        Optimised fast path: no checking whatsoever. Read bits are dumped.
199:        The caller is responsible for ensuring avail_in >= in_blklen before
200:        invoking the fast path.  As a defensive measure we clamp the byte
201:        load to avail_in; if fewer bytes than requested are available the
202:        accumulator is zero-padded and the returned value may be wrong, but
203:        we will not read past the end of the buffer.
204:      */
205: 
206:     struct internal_state *state = strm->state;
207:     if (state->bitp < n)
208:     {
209:         int b = (63 - state->bitp) >> 3;
210:         /* Clamp to available bytes – avail_in may have been drained by
211:          * earlier direct_get_fs calls within the same fast-path block. */
212:         if ((size_t)b > strm->avail_in)
213:             b = (int)strm->avail_in;
214:         if (b == 6) {
215:             state->acc = (state->acc << 48)
216:                 | ((uint64_t)strm->next_in[0] << 40)
217:                 | ((uint64_t)strm->next_in[1] << 32)
218:                 | ((uint64_t)strm->next_in[2] << 24)
219:                 | ((uint64_t)strm->next_in[3] << 16)
220:                 | ((uint64_t)strm->next_in[4] << 8)
221:                 | (uint64_t)strm->next_in[5];
222:         } else if (b == 7) {
223:             state->acc = (state->acc << 56)
224:                 | ((uint64_t)strm->next_in[0] << 48)
225:                 | ((uint64_t)strm->next_in[1] << 40)
226:                 | ((uint64_t)strm->next_in[2] << 32)
227:                 | ((uint64_t)strm->next_in[3] << 24)
228:                 | ((uint64_t)strm->next_in[4] << 16)
229:                 | ((uint64_t)strm->next_in[5] << 8)
230:                 | (uint64_t)strm->next_in[6];
231:         } else if (b == 5) {
232:             state->acc = (state->acc << 40)
233:                 | ((uint64_t)strm->next_in[0] << 32)
234:                 | ((uint64_t)strm->next_in[1] << 24)
235:                 | ((uint64_t)strm->next_in[2] << 16)
236:                 | ((uint64_t)strm->next_in[3] << 8)
237:                 | (uint64_t)strm->next_in[4];
238:         } else if (b == 4) {
239:             state->acc = (state->acc << 32)
240:                 | ((uint64_t)strm->next_in[0] << 24)
241:                 | ((uint64_t)strm->next_in[1] << 16)
242:                 | ((uint64_t)strm->next_in[2] << 8)
243:                 | (uint64_t)strm->next_in[3];
244:         } else if (b == 3) {
245:             state->acc = (state->acc << 24)
246:                 | ((uint64_t)strm->next_in[0] << 16)
247:                 | ((uint64_t)strm->next_in[1] << 8)
248:                 | (uint64_t)strm->next_in[2];
249:         } else if (b == 2) {
250:             state->acc = (state->acc << 16)
251:                 | ((uint64_t)strm->next_in[0] << 8)
252:                 | (uint64_t)strm->next_in[1];
253:         } else if (b == 1) {
254:             state->acc = (state->acc << 8)
255:                 | (uint64_t)strm->next_in[0];
256:         }
257:         strm->next_in += b;
258:         strm->avail_in -= b;
259:         state->bitp += b << 3;
260:     }
261: 
262:     if (state->bitp < n)
263:         return 0;  /* Ran out of input; return zero rather than undefined. */
264: 
265:     state->bitp -= n;
266:     return (state->acc >> state->bitp) & (UINT64_MAX >> (64 - n));
267: }
