269: static inline uint32_t direct_get_fs(struct aec_stream *strm)
270: {
271:     /**
272:        Interpret a Fundamental Sequence from the input buffer.
273: 
274:        Essentially counts the number of 0 bits until a 1 is
275:        encountered.
276:      */
277: 
278:     uint32_t fs = 0;
279:     struct internal_state *state = strm->state;
280: 
281:     if (state->bitp)
282:         state->acc &= UINT64_MAX >> (64 - state->bitp);
283:     else
284:         state->acc = 0;
285: 
286:     while (state->acc == 0) {
287:         if (strm->avail_in < 7)
288:             return 0;
289: 
290:         state->acc = (state->acc << 56)
291:             | ((uint64_t)strm->next_in[0] << 48)
292:             | ((uint64_t)strm->next_in[1] << 40)
293:             | ((uint64_t)strm->next_in[2] << 32)
294:             | ((uint64_t)strm->next_in[3] << 24)
295:             | ((uint64_t)strm->next_in[4] << 16)
296:             | ((uint64_t)strm->next_in[5] << 8)
297:             | (uint64_t)strm->next_in[6];
298:         strm->next_in += 7;
299:         strm->avail_in -= 7;
300:         fs += state->bitp;
301:         state->bitp = 56;
302:     }
303: 
304:     {
305: #ifndef __has_builtin
306: #define __has_builtin(x) 0  /* Compatibility with non-clang compilers. */
307: #endif
308: #if HAVE_DECL___BUILTIN_CLZLL || __has_builtin(__builtin_clzll)
309:         int i = 63 - __builtin_clzll(state->acc);
310: #elif defined HAVE_BSR64
311:         unsigned long i;
312:         _BitScanReverse64(&i, state->acc);
313: #else
314:         int i = state->bitp - 1;
315:         while ((state->acc & (UINT64_C(1) << i)) == 0)
316:             i--;
317: #endif
318:         fs += state->bitp - i - 1;
319:         state->bitp = i;
320:     }
321:     return fs;
322: }
323: 
324: static inline uint32_t bits_ask(struct aec_stream *strm, int n)
325: {
326:     while (strm->state->bitp < n) {
327:         if (strm->avail_in == 0)
328:             return 0;
329:         strm->avail_in--;
330:         strm->state->acc <<= 8;
331:         strm->state->acc |= *strm->next_in++;
332:         strm->state->bitp += 8;
333:     }
334:     return 1;
335: }
336: 
337: static inline uint32_t bits_get(struct aec_stream *strm, int n)
338: {
339:     return (strm->state->acc >> (strm->state->bitp - n))
340:         & (UINT64_MAX >> (64 - n));
341: }
342: 
343: static inline void bits_drop(struct aec_stream *strm, int n)
344: {
345:     strm->state->bitp -= n;
346: }
347: 
348: static inline uint32_t fs_ask(struct aec_stream *strm)
349: {
350:     if (bits_ask(strm, 1) == 0)
351:         return 0;
352:     while ((strm->state->acc & (UINT64_C(1) << (strm->state->bitp - 1))) == 0) {
353:         if (strm->state->bitp == 1) {
354:             if (strm->avail_in == 0)
355:                 return 0;
356:             strm->avail_in--;
357:             strm->state->acc <<= 8;
358:             strm->state->acc |= *strm->next_in++;
359:             strm->state->bitp += 8;
360:         }
361:         strm->state->fs++;
362:         strm->state->bitp--;
363:     }
364:     return 1;
365: }
366: 
367: static inline void fs_drop(struct aec_stream *strm)
368: {
369:     strm->state->fs = 0;
370:     strm->state->bitp--;
371: }
372: 
373: static inline uint32_t copysample(struct aec_stream *strm)
374: {
375:     if (bits_ask(strm, strm->bits_per_sample) == 0
376:         || strm->avail_out < strm->state->bytes_per_sample)
377:         return 0;
378: 
379:     put_sample(strm, bits_get(strm, strm->bits_per_sample));
380:     bits_drop(strm, strm->bits_per_sample);
381:     return 1;
382: }
383: 
384: static inline int m_id(struct aec_stream *strm)
385: {
386:     struct internal_state *state = strm->state;
387:     if (strm->avail_in >= strm->state->in_blklen) {
388:         state->id = direct_get(strm, state->id_len);
389:     } else {
390:         if (bits_ask(strm, state->id_len) == 0) {
391:             state->mode = m_id;
392:             return M_EXIT;
393:         }
394:         state->id = bits_get(strm, state->id_len);
395:         bits_drop(strm, state->id_len);
396:     }
397:     state->mode = state->id_table[state->id];
398:     return(state->mode(strm));
399: }
400: 
401: static int m_next_cds(struct aec_stream *strm)
402: {
403:     struct internal_state *state = strm->state;
404: 
405:     if ((state->offsets != NULL) && (state->rsi_size == RSI_USED_SIZE(state)))
406:         vector_push_back(
407:             state->offsets,
408:             strm->total_in * 8 - (strm->avail_in * 8 + state->bitp));
409: 
410:     if (state->rsi_size == RSI_USED_SIZE(state)) {
411:         state->flush_output(strm);
412:         state->flush_start = state->rsi_buffer;
413:         state->rsip = state->rsi_buffer;
414:         if (state->pp) {
415:             state->ref = 1;
416:             state->encoded_block_size = strm->block_size - 1;
417:         }
418:         if (strm->flags & AEC_PAD_RSI)
419:             state->bitp -= state->bitp % 8;
420:     } else {
421:         state->ref = 0;
422:         state->encoded_block_size = strm->block_size;
423:     }
424:     return m_id(strm);
425: }
426: 
427: static int m_split_output(struct aec_stream *strm)
428: {
429:     struct internal_state *state = strm->state;
430:     int k = state->id - 1;
431: 
432:     do {
433:         if (bits_ask(strm, k) == 0 || strm->avail_out < state->bytes_per_sample)
434:             return M_EXIT;
435:         if (k)
436:             *state->rsip++ += bits_get(strm, k);
437:         else
438:             state->rsip++;
439:         strm->avail_out -= state->bytes_per_sample;
440:         bits_drop(strm, k);
441:     } while(++state->sample_counter < state->encoded_block_size);
442: 
443:     state->mode = m_next_cds;
444:     return M_CONTINUE;
445: }
446: 
447: static int m_split_fs(struct aec_stream *strm)
448: {
449:     struct internal_state *state = strm->state;
450:     int k = state->id - 1;
451: 
452:     do {
453:         if (fs_ask(strm) == 0)
454:             return M_EXIT;
455:         state->rsip[state->sample_counter] = state->fs << k;
456:         fs_drop(strm);
457:     } while(++state->sample_counter < state->encoded_block_size);
458: 
459:     state->sample_counter = 0;
460:     state->mode = m_split_output;
461: 
462:     return M_CONTINUE;
463: }
464: 
465: static int m_split(struct aec_stream *strm)
466: {
467:     struct internal_state *state = strm->state;
468: 
469:     if (BUFFERSPACE(strm)) {
470:         int k = state->id - 1;
471:         size_t binary_part = (k * state->encoded_block_size) / 8 + 9;
472: 
473:         /* Check input availability before any side effects on rsip so
474:          * that a premature M_ERROR doesn't leave rsip partially
475:          * advanced and corrupt the rsi_buffer on a subsequent call. */
476:         if (k && strm->avail_in < binary_part)
477:             return M_ERROR;
478: 
479:         if (state->ref)
480:             *state->rsip++ = direct_get(strm, strm->bits_per_sample);
481: 
482:         for (size_t i = 0; i < state->encoded_block_size; i++)
483:             state->rsip[i] = direct_get_fs(strm) << k;
484: 
485:         if (k) {
486:             for (size_t i = 0; i < state->encoded_block_size; i++)
487:                 *state->rsip++ += direct_get(strm, k);
488:         } else {
489:             state->rsip += state->encoded_block_size;
490:         }
491: 
492:         strm->avail_out -= state->out_blklen;
493:         state->mode = m_next_cds;
494:     } else {
495:         if (state->ref && (copysample(strm) == 0))
496:             return M_EXIT;
497:         state->sample_counter = 0;
498:         state->mode = m_split_fs;
499:     }
500:     return M_CONTINUE;
501: }
502: 
503: static int m_zero_output(struct aec_stream *strm)
504: {
505:     struct internal_state *state = strm->state;
506: 
507:     do {
508:         if (strm->avail_out < state->bytes_per_sample)
509:             return M_EXIT;
510:         put_sample(strm, 0);
511:     } while(--state->sample_counter);
512: 
513:     state->mode = m_next_cds;
514:     return M_CONTINUE;
515: }
516: 
517: static int m_zero_block(struct aec_stream *strm)
518: {
519:     struct internal_state *state = strm->state;
520:     uint32_t zero_blocks;
521:     uint32_t zero_samples;
522:     uint32_t zero_bytes;
523: 
524:     if (fs_ask(strm) == 0)
525:         return M_EXIT;
526: 
527:     zero_blocks = state->fs + 1;
528:     fs_drop(strm);
529: 
530:     if (zero_blocks == ROS) {
531:         int b = (int)RSI_USED_SIZE(state) / strm->block_size;
532:         zero_blocks = MIN((int)(strm->rsi - b), 64 - (b % 64));
533:     } else if (zero_blocks > ROS) {
534:         zero_blocks--;
535:     }
536: 
537:     if (zero_blocks > UINT32_MAX / strm->block_size)
538:         return M_ERROR;
539:     zero_samples = zero_blocks * strm->block_size - state->ref;
540:     if (state->rsi_size - RSI_USED_SIZE(state) < zero_samples)
541:         return M_ERROR;
542: 
543:     zero_bytes = zero_samples * state->bytes_per_sample;
544:     if (strm->avail_out >= zero_bytes) {
545:         memset(state->rsip, 0, zero_samples * sizeof(uint32_t));
546:         state->rsip += zero_samples;
547:         strm->avail_out -= zero_bytes;
548:         state->mode = m_next_cds;
549:     } else {
550:         state->sample_counter = zero_samples;
551:         state->mode = m_zero_output;
552:     }
553:     return M_CONTINUE;
554: }
555: 
556: static int m_se_decode(struct aec_stream *strm)
557: {
558:     struct internal_state *state = strm->state;
559: 
560:     while(state->sample_counter < strm->block_size) {
561:         int32_t m;
562:         int32_t d1;
563:         if (fs_ask(strm) == 0)
564:             return M_EXIT;
565:         m = state->fs;
566:         if (m > SE_TABLE_SIZE)
567:             return M_ERROR;
568:         d1 = m - state->se_table[2 * m + 1];
569: 
570:         if ((state->sample_counter & 1) == 0) {
571:             if (strm->avail_out < state->bytes_per_sample)
572:                 return M_EXIT;
573:             put_sample(strm, state->se_table[2 * m] - d1);
574:             state->sample_counter++;
575:         }
576: 
577:         if (strm->avail_out < state->bytes_per_sample)
578:             return M_EXIT;
579:         put_sample(strm, d1);
580:         state->sample_counter++;
581:         fs_drop(strm);
582:     }
583: 
584:     state->mode = m_next_cds;
585:     return M_CONTINUE;
586: }
587: 
588: static int m_se(struct aec_stream *strm)
589: {
590:     struct internal_state *state = strm->state;
591: 
592:     if (BUFFERSPACE(strm)) {
593:         uint32_t i = state->ref;
594: 
595:         while (i < strm->block_size) {
596:             uint32_t m = direct_get_fs(strm);
597:             int32_t d1;
598: 
599:             if (m > SE_TABLE_SIZE)
600:                 return M_ERROR;
601: 
602:             d1 = m - state->se_table[2 * m + 1];
603: 
604:             if ((i & 1) == 0) {
605:                 put_sample(strm, state->se_table[2 * m] - d1);
606:                 i++;
607:             }
608:             put_sample(strm, d1);
609:             i++;
610:         }
611:         state->mode = m_next_cds;
612:     } else {
613:         state->mode = m_se_decode;
614:         state->sample_counter = state->ref;
615:     }
616:     return M_CONTINUE;
617: }
618: 
619: static int m_low_entropy_ref(struct aec_stream *strm)
620: {
621:     struct internal_state *state = strm->state;
622: 
623:     if (state->ref && copysample(strm) == 0)
624:         return M_EXIT;
625: 
626:     if (state->id == 1)
627:         state->mode = m_se;
628:     else
629:         state->mode = m_zero_block;
630:     return M_CONTINUE;
631: }
632: 
633: static int m_low_entropy(struct aec_stream *strm)
634: {
635:     struct internal_state *state = strm->state;
636: 
637:     if (bits_ask(strm, 1) == 0)
638:         return M_EXIT;
639:     state->id = bits_get(strm, 1);
640:     bits_drop(strm, 1);
641:     state->mode = m_low_entropy_ref;
642:     return M_CONTINUE;
643: }
644: 
645: static int m_uncomp_copy(struct aec_stream *strm)
646: {
647:     struct internal_state *state = strm->state;
648: 
649:     do {
650:         if (copysample(strm) == 0)
651:             return M_EXIT;
652:     } while(--state->sample_counter);
653: 
654:     state->mode = m_next_cds;
655:     return M_CONTINUE;
656: }
657: 
658: static int m_uncomp(struct aec_stream *strm)
659: {
660:     struct internal_state *state = strm->state;
661: 
662:     if (BUFFERSPACE(strm)) {
663:         for (size_t i = 0; i < strm->block_size; i++)
664:             *state->rsip++ = direct_get(strm, strm->bits_per_sample);
665:         strm->avail_out -= state->out_blklen;
666:         state->mode = m_next_cds;
667:     } else {
668:         state->sample_counter = strm->block_size;
669:         state->mode = m_uncomp_copy;
670:     }
671:     return M_CONTINUE;
672: }
673: 
674: static void create_se_table(int *table)
675: {
676:     int k = 0;
677:     for (int i = 0; i < 13; i++) {
678:         int ms = k;
679:         for (int j = 0; j <= i; j++) {
680:             table[2 * k] = i;
681:             table[2 * k + 1] = ms;
682:             k++;
683:         }
684:     }
685: }
686: 
687: int aec_decode_init(struct aec_stream *strm)
688: {
689:     struct internal_state *state;
690:     int modi;
691: 
692:     if (strm->bits_per_sample > 32
693:         || strm->bits_per_sample == 0
694:         || strm->rsi == 0
695:         || strm->rsi > 4096
696:         || strm->block_size & 1
697:         || strm->block_size > 256
698:         || strm->block_size == 0)
699:         return AEC_CONF_ERROR;
700: 
701:     state = malloc(sizeof(struct internal_state));
702:     if (state == NULL)
703:         return AEC_MEM_ERROR;
704:     memset(state, 0, sizeof(struct internal_state));
705: 
706:     create_se_table(state->se_table);
707: 
708:     strm->state = state;
709: 
710:     if (strm->bits_per_sample > 16) {
711:         state->id_len = 5;
712: 
713:         if (strm->bits_per_sample <= 24 && strm->flags & AEC_DATA_3BYTE) {
714:             state->bytes_per_sample = 3;
715:             if (strm->flags & AEC_DATA_MSB)
716:                 state->flush_output = flush_msb_24;
717:             else
718:                 state->flush_output = flush_lsb_24;
719:         } else {
720:             state->bytes_per_sample = 4;
721:             if (strm->flags & AEC_DATA_MSB)
722:                 state->flush_output = flush_msb_32;
723:             else
724:                 state->flush_output = flush_lsb_32;
725:         }
726:         state->out_blklen = strm->block_size * state->bytes_per_sample;
727:     }
728:     else if (strm->bits_per_sample > 8) {
729:         state->bytes_per_sample = 2;
730:         state->id_len = 4;
731:         state->out_blklen = strm->block_size * 2;
732:         if (strm->flags & AEC_DATA_MSB)
733:             state->flush_output = flush_msb_16;
734:         else
735:             state->flush_output = flush_lsb_16;
736:     } else {
737:         if (strm->flags & AEC_RESTRICTED) {
738:             if (strm->bits_per_sample <= 4) {
739:                 if (strm->bits_per_sample <= 2)
740:                     state->id_len = 1;
741:                 else
742:                     state->id_len = 2;
743:             } else {
744:                 free(state);
745:                 return AEC_CONF_ERROR;
746:             }
747:         } else {
748:             state->id_len = 3;
749:         }
750: 
751:         state->bytes_per_sample = 1;
752:         state->out_blklen = strm->block_size;
753:         state->flush_output = flush_8;
754:     }
755: 
756:     if (strm->flags & AEC_DATA_SIGNED) {
757:         state->xmax = (INT64_C(1) << (strm->bits_per_sample - 1)) - 1;
758:         state->xmin = ~state->xmax;
759:     } else {
760:         state->xmin = 0;
761:         state->xmax = (UINT64_C(1) << strm->bits_per_sample) - 1;
762:     }
763: 
764:     state->in_blklen = (strm->block_size * strm->bits_per_sample
765:                         + state->id_len) / 8 + 16;
766: 
767:     modi = 1UL << state->id_len;
768:     state->id_table = malloc(modi * sizeof(int (*)(struct aec_stream *)));
769:     if (state->id_table == NULL) {
770:         free(state);
771:         return AEC_MEM_ERROR;
772:     }
773: 
774:     state->id_table[0] = m_low_entropy;
775:     for (int i = 1; i < modi - 1; i++) {
776:         state->id_table[i] = m_split;
777:     }
778:     state->id_table[modi - 1] = m_uncomp;
779: 
780:     state->rsi_size = strm->rsi * strm->block_size;
781:     state->rsi_buffer = malloc(state->rsi_size * sizeof(uint32_t));
782:     if (state->rsi_buffer == NULL) {
783:         free(state->id_table);
784:         free(state);
785:         return AEC_MEM_ERROR;
786:     }
787: 
788:     state->pp = strm->flags & AEC_DATA_PREPROCESS;
789:     if (state->pp) {
790:         state->ref = 1;
791:         state->encoded_block_size = strm->block_size - 1;
792:     } else {
793:         state->ref = 0;
794:         state->encoded_block_size = strm->block_size;
795:     }
796:     strm->total_in = 0;
797:     strm->total_out = 0;
798: 
799:     state->rsip = state->rsi_buffer;
800:     state->flush_start = state->rsi_buffer;
801:     state->bitp = 0;
802:     state->fs = 0;
803:     state->mode = m_id;
804:     state->offsets = NULL;
805: 
806:     return AEC_OK;
807: }
808: 
809: int aec_decode(struct aec_stream *strm, int flush)
810: {
811:     /**
812:        Finite-state machine implementation of the adaptive entropy
813:        decoder.
814: 
815:        Can work with one byte input und one sample output buffers. If
816:        enough buffer space is available, then faster implementations
817:        of the states are called. Inspired by zlib.
818:     */
819: 
820:     struct internal_state *state = strm->state;
821:     int status;
822: 
823:     strm->total_in += strm->avail_in;
824:     strm->total_out += strm->avail_out;
825: 
826:     do {
827:         status = state->mode(strm);
828:     } while (status == M_CONTINUE);
829: 
830:     if (status == M_ERROR)
831:         return AEC_DATA_ERROR;
832: 
833:     if (status == M_EXIT && strm->avail_out > 0 &&
834:         strm->avail_out < state->bytes_per_sample) {
835:         /* Flush the samples already decoded into rsi_buffer so that
836:          * next_out and avail_out remain consistent with each other.
837:          * The caller can detect partial output via AEC_MEM_ERROR. */
838:         state->flush_output(strm);
839:         strm->total_in -= strm->avail_in;
840:         strm->total_out -= strm->avail_out;
841:         return AEC_MEM_ERROR;
842:     }
843: 
844:     state->flush_output(strm);
845: 
846:     strm->total_in -= strm->avail_in;
847:     strm->total_out -= strm->avail_out;
848: 
849:     return AEC_OK;
850: }
851: 
852: int aec_decode_end(struct aec_stream *strm)
853: {
854:     struct internal_state *state = strm->state;
855:     if (state->offsets != NULL)
856:         vector_destroy(state->offsets);
857: 
858:     free(state->id_table);
859:     free(state->rsi_buffer);
860:     free(state);
861: 
862:     return AEC_OK;
863: }
864: 
865: int aec_buffer_decode(struct aec_stream *strm)
866: {
867:     int status = aec_decode_init(strm);
868:     if (status != AEC_OK)
869:         return status;
870: 
871:     status = aec_decode(strm, AEC_FLUSH);
872:     aec_decode_end(strm);
873:     return status;
874: }
875: 
876: int aec_buffer_seek(struct aec_stream *strm, size_t offset)
877: {
878:     struct internal_state *state = strm->state;
879: 
880:     size_t byte_offset = offset / 8;
881:     unsigned char bit_offset = offset % 8;
882: 
883:     if (strm->avail_in < byte_offset)
884:         return AEC_MEM_ERROR;
885: 
886:     strm->next_in += byte_offset;
887:     strm->avail_in -= byte_offset;
888: 
889:     if (bit_offset > 0) {
890:         if (strm->avail_in < 1)
891:             return AEC_MEM_ERROR;
892: 
893:         state->acc = (uint64_t)strm->next_in[0];
894:         state->bitp = 8 - bit_offset;
895:         strm->next_in++;
896:         strm->avail_in--;
897:     }
898:     return AEC_OK;
899: }
900: 
901: int aec_decode_range(struct aec_stream *strm, const size_t *rsi_offsets, size_t rsi_offsets_count, size_t pos, size_t size)
902: {
903:     struct internal_state *state = strm->state;
904:     int status;
905:     size_t rsi_size;
906:     size_t rsi_n;
907:     unsigned char *out_tmp;
908:     struct aec_stream strm_tmp = *strm;
